#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.loanSign_Evoke)]
    public class LoanSign_Evoke : ContraptionEvokeBehaviour
    {
        public LoanSign_Evoke(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Evoke(Entity entity)
        {
            base.Evoke(entity);
            LoanSign.Repay(entity, 1);
        }
    }
